def general_sets(apps, schema_editor):
    """Bell times entered before R18-3 become each branch's "General" set (every class, every campus)."""
    Period = apps.get_model("academics", "Period")
    BellSet = apps.get_model("academics", "BellSet")
    for branch_id in Period.objects.filter(bell_set__isnull=True).values_list("branch_id", flat=True).distinct():
        bell = BellSet.objects.create(branch_id=branch_id, name="General")
        Period.objects.filter(branch_id=branch_id, bell_set__isnull=True).update(bell_set=bell)


